mapper.select:
SELECT P.PO_NO AS poNo , P.PO_DT AS poDt , P.VEND_CD AS vendCd , V.VEND_NM AS vendNm , P.ITEM_CD AS itemCd , P.QTY AS qty , P.UNIT_PRICE AS unitPrice , P.STTS_CD AS sttsCd FROM TB_PO P LEFT JOIN TB_VEND V ON V.VEND_CD = P.VEND_CD WHERE P.PO_DT BETWEEN #{fromDt} AND #{toDt}
AND P.VEND_CD = #{vendCd}
AND P.STTS_CD = #{sttsCd}
ORDER BY P.PO_NO DESC

mapper.update:
UPDATE TB_PO
   SET STTS_CD = #{sttsCd}
     , UPD_DT = SYSDATE
 WHERE PO_NO = #{poNo}
